from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(a: int, b: int) -> bool:
            root_a = find(a)
            root_b = find(b)
            if root_a == root_b:
                return False
            parent[root_a] = root_b
            return True

        property_sets = [set(row) for row in properties]
        components = n

        for i in range(n):
            for j in range(i + 1, n):
                if len(property_sets[i] & property_sets[j]) >= k:
                    if union(i, j):
                        components -= 1

        return components
